import React, { useState } from 'react';

import { omitTransientProps } from 'utils/emotion';

import {
  BEES_ALERT_ILLUSTRATION,
  IMAGE_DEFAULT_ASPECT_RATIO,
} from './Image.constants';
import {
  StyledErrorIllustration,
  StyledImageContainer,
  StyledImageElement,
  StyledImageOverlay,
} from './Image.styles';
import type { ImageProps } from './Image.types';

export const Image = React.forwardRef<HTMLDivElement, ImageProps>(
  (
    {
      aspectRatio = IMAGE_DEFAULT_ASPECT_RATIO,
      className,
      customErrorImage,
      disabled = false,
      isInteractive = false,
      onError,
      position,
      src,
      variant = 'fill',
      ...props
    },
    forwardedRef,
  ) => {
    const [hasError, setHasError] = useState(false);
    const [hasCustomImageError, setHasCustomImageError] = useState(false);

    if (hasError) {
      const { width, height } = props;

      return (
        <StyledErrorIllustration className={className} ref={forwardedRef}>
          {!hasCustomImageError && customErrorImage ? (
            <img
              {...omitTransientProps(props)}
              alt={customErrorImage.alt}
              height={height}
              onError={() => {
                // eslint-disable-next-line no-console
                console.warn(
                  "The custom image provided wasn't able to load, the default image will be used instead.",
                );
                setHasCustomImageError(true);
              }}
              src={customErrorImage.src}
              width={width}
            />
          ) : (
            <img
              {...omitTransientProps(props)}
              alt={BEES_ALERT_ILLUSTRATION.alt}
              height={height}
              src={BEES_ALERT_ILLUSTRATION.src}
              width={width}
            />
          )}
        </StyledErrorIllustration>
      );
    }

    return (
      <StyledImageContainer ref={forwardedRef}>
        <StyledImageElement
          {...omitTransientProps(props)}
          $aspectRatio={aspectRatio}
          $position={position}
          $variant={variant}
          className={className}
          onError={(event) => {
            onError?.(event);
            setHasError(true);
          }}
          src={src}
        />
        {isInteractive ? <StyledImageOverlay $isDisabled={disabled} /> : null}
      </StyledImageContainer>
    );
  },
);

Image.displayName = 'Image';
